export const escapeHTML = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function parse(source) {
  if(source.length>16000) throw Error('Please use no more than 16,000 characters.');
  const lines=source.split(/\r?\n/).map((s,i)=>({text:s.trim(),line:i+1})).filter(x=>x.text&&!x.text.startsWith('//'));
  if(lines.length>180)throw Error('Please use no more than 180 non-empty lines.');
  let i=0;const modules=[];
  const error=(message,x=lines[i])=>{throw Error(`${x?'Line '+x.line+': ':''}${message}`)};
  function block(stops=[],depth=0){if(depth>6)error('Limit nesting to six levels.');const out=[];
    while(i<lines.length){const x=lines[i],t=x.text,u=t.toUpperCase();if(stops.some(s=>s.test(u)))break;
      let m;
      if(u==='BEGIN'){i++;const body=block([/^END$/],depth+1);if(lines[i]?.text.toUpperCase()!=='END')error('BEGIN needs a matching END.',x);i++;out.push(...body);}
      else if((m=t.match(/^IF\s+(.+)\s+THEN$/i))){i++;const yes=block([/^ELSE$/,/^ENDIF$/],depth+1);let no=[];if(lines[i]?.text.toUpperCase()==='ELSE'){i++;no=block([/^ENDIF$/],depth+1)}if(lines[i]?.text.toUpperCase()!=='ENDIF')error('IF needs ENDIF. Use nested IF inside ELSE for another condition.',x);i++;out.push({type:'if',condition:m[1],yes,no,line:x.line});}
      else if((m=t.match(/^WHILE\s+(.+)\s+DO$/i))){i++;const body=block([/^ENDWHILE$/],depth+1);if(lines[i]?.text.toUpperCase()!=='ENDWHILE')error('WHILE needs ENDWHILE.',x);i++;out.push({type:'while',condition:m[1],body,line:x.line});}
      else if((m=t.match(/^FOR\s+([A-Za-z_]\w*)\s*=\s*(.+?)\s+TO\s+(.+?)(?:\s+STEP\s+(-?\d+))?$/i))){if(Number(m[4])===0)error('STEP cannot be zero.',x);i++;const body=block([/^ENDFOR$/],depth+1);if(lines[i]?.text.toUpperCase()!=='ENDFOR')error('FOR needs ENDFOR.',x);i++;out.push({type:'for',variable:m[1],from:m[2],to:m[3],step:Number(m[4]||1),body,line:x.line});}
      else if(u==='REPEAT'){i++;const body=block([/^UNTIL\s+/],depth+1);const end=lines[i]?.text.match(/^UNTIL\s+(.+)$/i);if(!end)error('REPEAT needs UNTIL followed by a condition.',x);i++;out.push({type:'repeat',condition:end[1],body,line:x.line});}
      else if((m=t.match(/^CASE\s+(.+)\s+OF$/i))){i++;const branches=[];let otherwise=[];while(i<lines.length&&!/^ENDCASE$/i.test(lines[i].text)){const w=lines[i].text.match(/^WHEN\s+(.+):$/i);if(w){i++;branches.push({value:w[1],body:block([/^WHEN\s+/ ,/^OTHERWISE:$/,/^ENDCASE$/],depth+1)})}else if(/^OTHERWISE:$/i.test(lines[i].text)){i++;otherwise=block([/^ENDCASE$/],depth+1);break;}else error('CASE expects WHEN value: or OTHERWISE:.');}if(!/^ENDCASE$/i.test(lines[i]?.text||''))error('CASE needs ENDCASE.',x);if(!branches.length)error('CASE needs at least one WHEN branch.',x);i++;let tail=otherwise;for(const b of branches.reverse())tail=[{type:'if',condition:`${m[1]} = ${b.value}`,yes:b.body,no:tail,line:x.line}];out.push(...tail);}
      else if((m=t.match(/^(PROCEDURE|FUNCTION)\s+([A-Za-z_]\w*)\s*\(([^)]*)\)(?:\s+RETURNS\s+\w+)?$/i))){if(depth>0)error('Define methods outside BEGIN/END and other blocks.',x);if(modules.some(q=>q.name.toLowerCase()===m[2].toLowerCase()))error('Method names must be unique in the chart lab. Overloading is taught in lessons.',x);i++;const end='END'+m[1].toUpperCase();const body=block([new RegExp('^'+end+'$')],depth+1);if(lines[i]?.text.toUpperCase()!==end)error('Method needs '+end+'.',x);i++;modules.push({name:m[2],parameters:m[3],kind:m[1].toLowerCase(),body});}
      else if((m=t.match(/^CALL\s+([A-Za-z_]\w*)\s*\((.*)\)$/i))){out.push({type:'call',name:m[1],label:t,line:x.line});i++;}
      else if(/^INPUT\s+.+$/i.test(t)||/^OUTPUT\s+.+$/i.test(t)){out.push({type:'io',label:t,line:x.line});i++;}
      else if(/^DECLARE\s+.+\s+AS\s+(INTEGER|REAL|STRING|BOOLEAN)(?:\s*=\s*.+)?$/i.test(t)||/^SET\s+[A-Za-z_]\w*(?:\[[^\]]+\])*\s*=\s*.+$/i.test(t)||/^RETURN(?:\s+.+)?$/i.test(t)){out.push({type:'process',label:t,line:x.line});i++;}
      else if(/^(END|ENDIF|ENDWHILE|ENDFOR|ENDCASE|ENDPROCEDURE|ENDFUNCTION|ELSE|UNTIL)(?:\s|$)/i.test(t))error('Unexpected '+t+'. Check matching opening and closing blocks.',x);
      else error('Unsupported or incomplete statement. Use the syntax guide below the editor.',x);
    }return out;
  }
  const main=block();if(i<lines.length)error('Unexpected closing statement.');if(!main.length&&!modules.length)throw Error('Enter some pseudocode first.');return {main,modules};
}
function words(text,max=30){const words=String(text).split(/\s+/),out=[];let row='';for(const w of words){if((row+' '+w).trim().length>max&&row){out.push(row);row=w}else row=(row+' '+w).trim()}if(row)out.push(row);return out;}
function svgText(text,x,y){const rows=words(text).slice(0,4);return `<text x="${x}" y="${y-(rows.length-1)*8}" text-anchor="middle" dominant-baseline="middle" font-family="Arial,sans-serif" font-size="13" fill="#172a43">${rows.map((r,i)=>`<tspan x="${x}" dy="${i?17:0}">${escapeHTML(r)}</tspan>`).join('')}</text>`}
function shell(body,w,h,title){return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${escapeHTML(title)}"><title>${escapeHTML(title)}</title><defs><marker id="arrow" markerWidth="9" markerHeight="7" refX="8" refY="3.5" orient="auto"><path d="M0 0 L9 3.5 L0 7" fill="#66758c"/></marker></defs><rect width="100%" height="100%" fill="#fcfcff"/>${body}</svg>`}
export function flowchart(ast,module='main'){
 const sequence=module==='main'?ast.main:ast.modules.find(m=>m.name===module)?.body;if(!sequence)throw Error('Unknown method.');
 const containsReturn=list=>list.some(n=>/^RETURN(?:\s|$)/i.test(n.label||'')||containsReturn(n.yes||[])||containsReturn(n.no||[])||containsReturn(n.body||[]));
 if(containsReturn(sequence))throw Error('Flowcharts with RETURN are not supported in this release. Use the hierarchy view for method organisation.');
 let nodes=[],edges=[];let maxX=500,minX=0;
 const point=(x,y)=>({x,y});
 const edge=(a,b,label='',via=[])=>{const pts=[a,...via,b];edges.push(`<path d="M${pts.map(p=>`${p.x} ${p.y}`).join(' L')}" fill="none" stroke="#66758c" stroke-width="1.6" marker-end="url(#arrow)"/>${label?`<text x="${(a.x+(via[0]?.x??b.x))/2+6}" y="${a.y+17}" font-size="11" font-family="Arial" fill="#52617b">${escapeHTML(label)}</text>`:''}`)};
 const node=(type,label,x,y)=>{const w=240,h=type==='decision'?104:72;maxX=Math.max(maxX,x+w/2+45);minX=Math.min(minX,x-w/2-45);const fill=type==='decision'?'#fff0ce':type==='io'?'#e2f2ec':type==='terminal'?'#eae7fc':'#fff';let shape=type==='decision'?`<polygon points="${x},${y} ${x+w/2},${y+h/2} ${x},${y+h} ${x-w/2},${y+h/2}"/>`:type==='io'?`<polygon points="${x-w/2+18},${y} ${x+w/2},${y} ${x+w/2-18},${y+h} ${x-w/2},${y+h}"/>`:`<rect x="${x-w/2}" y="${y}" width="${w}" height="${h}" rx="${type==='terminal'?36:7}"/>`;nodes.push(`<g fill="${fill}" stroke="#a5adc0" stroke-width="1.3"><title>${escapeHTML(label)}</title>${shape}</g>${type==='call'?`<path d="M${x-100} ${y}v${h}M${x+100} ${y}v${h}" stroke="#a5adc0"/>`:''}${svgText(label,x,y+h/2)}`);return{top:point(x,y),bottom:point(x,y+h),left:point(x-w/2,y+h/2),right:point(x+w/2,y+h/2),h};};
 const width=list=>Math.max(320,...list.map(n=>n.type==='if'?width(n.yes)+width(n.no)+60:n.body?width(n.body)+320:320));
 function draw(list,x,y){let first=null,prev=null,cursor=y;
   for(const n of list){let entry,exit;
    if(n.type==='if'){const test=node('decision',n.condition,x,cursor);entry=test.top;const wl=width(n.yes),wr=width(n.no),lx=x-(wr+80)/2,rx=x+(wl+80)/2;const yes=draw(n.yes,lx,cursor+155),no=draw(n.no,rx,cursor+155);edge(test.left,yes.start,'True',[point(lx,test.left.y)]);edge(test.right,no.start,'False',[point(rx,test.right.y)]);const bottom=Math.max(yes.end.y,no.end.y)+45;exit=point(x,bottom);edge(yes.end,exit,'',[point(lx,bottom)]);edge(no.end,exit,'',[point(rx,bottom)]);cursor=bottom+55;
    }else if(n.type==='while'||n.type==='for'){let initial=null;if(n.type==='for'){initial=node('process',`SET ${n.variable} = ${n.from}`,x,cursor);cursor+=110;}const condition=n.type==='for'?`${n.variable} ${n.step>0?'<=':'>='} ${n.to}`:n.condition;const test=node('decision',condition,x,cursor);entry=initial?initial.top:test.top;if(initial)edge(initial.bottom,test.top);const body=draw(n.body,x,cursor+160);edge(test.bottom,body.start,'True');let end=body.end;if(n.type==='for'){const inc=node('process',`SET ${n.variable} = ${n.variable} ${n.step>0?'+':'-'} ${Math.abs(n.step)}`,x,end.y+40);edge(end,inc.top);end=inc.bottom;}const side=width(n.body)/2+70;maxX=Math.max(maxX,x+side+40);minX=Math.min(minX,x-side-40);edge(end,test.right,'',[point(x,end.y+30),point(x+side,end.y+30),point(x+side,test.right.y)]);exit=point(x,end.y+95);edge(test.left,exit,'False',[point(x-side,test.left.y),point(x-side,exit.y)]);cursor=exit.y+55;
    }else if(n.type==='repeat'){const anchor=point(x,cursor);const body=draw(n.body,x,cursor+30);entry=anchor;edge(anchor,body.start);const test=node('decision',n.condition,x,body.end.y+45);edge(body.end,test.top);const side=width(n.body)/2+60;minX=Math.min(minX,x-side-40);edge(test.left,anchor,'False',[point(x-side,test.left.y),point(x-side,anchor.y)]);exit=point(x,test.bottom.y+55);edge(test.bottom,exit,'True');cursor=exit.y+55;
    }else{const shape=node(n.type,n.label,x,cursor);entry=shape.top;exit=shape.bottom;cursor+=112;}
    if(!first)first=entry;if(prev)edge(prev,entry);prev=exit;
   }
   if(!first){const p=node('process','Continue',x,cursor);first=p.top;prev=p.bottom;}return{start:first,end:prev};
 }
 const w=width(sequence),cx=w/2;const start=node('terminal',module==='main'?'Start':module,cx,28);const body=draw(sequence,cx,145);edge(start.bottom,body.start);const end=node('terminal','End',cx,body.end.y+45);edge(body.end,end.top);const shift=minX<0?-minX:0;const totalW=Math.max(w,maxX)+shift;const height=end.bottom.y+35;if(totalW>18000||height>30000)throw Error('This chart is too large. Split the program into smaller methods.');return shell(`<g transform="translate(${shift} 0)">${edges.join('')}${nodes.join('')}</g>`,totalW,height,'Flowchart for '+module);
}
export function hierarchy(ast){
 const modules=new Map(ast.modules.map(m=>[m.name.toLowerCase(),m]));const relations=[],missing=new Set();const calls=(body)=>body.flatMap(n=>[...(n.type==='call'?[n.name]:[...String(n.label||'').matchAll(/\b([A-Za-z_]\w*)\s*\(/g)].map(m=>m[1]).filter(name=>modules.has(name.toLowerCase()))),...calls(n.yes||[]),...calls(n.no||[]),...calls(n.body||[])]);
 for(const [name,body]of [['Main',ast.main],...ast.modules.map(m=>[m.name,m.body])])for(const c of new Set(calls(body))){const resolved=modules.get(c.toLowerCase())?.name||c;relations.push([name,resolved]);if(!modules.has(c.toLowerCase()))missing.add(c);}
 const names=['Main',...ast.modules.map(m=>m.name),...missing];const unique=[...new Set(names)];const depth=new Map([['Main',0]]);for(let i=0;i<unique.length;i++)for(const[a,b]of relations)if(depth.has(a)&&!depth.has(b))depth.set(b,Math.min(5,depth.get(a)+1));for(const n of unique)if(!depth.has(n))depth.set(n,1);
 const levels=[];for(const n of unique)(levels[depth.get(n)]??=[]).push(n);const cols=Math.max(...levels.map(l=>l?.length||0),1),w=Math.max(600,cols*270+60),pos=new Map();let shapes='';levels.forEach((level,d)=>level?.forEach((name,i)=>{const x=w/2+(i-(level.length-1)/2)*270,y=45+d*160;pos.set(name,{x,y});shapes+=`<rect x="${x-115}" y="${y}" width="230" height="80" rx="8" fill="${name==='Main'?'#eae7fc':'#e2f2ec'}" stroke="#a5adc0"/>${svgText(name,x,y+40)}`;}));let edges='';for(const[a,b]of relations){const p=pos.get(a),q=pos.get(b);edges+=`<path d="M${p.x} ${p.y+80} L${q.x} ${q.y}" fill="none" stroke="#66758c" stroke-width="1.5" marker-end="url(#arrow)"/>`;}return {svg:shell(edges+shapes,w,levels.length*160+70,'Module call hierarchy'),missing:[...missing]};
}
export function classDiagram(){return shell(`<g fill="#fff" stroke="#a5adc0"><rect x="50" y="40" width="260" height="200" rx="8"/><rect x="400" y="40" width="260" height="200" rx="8"/><path d="M50 100H310M50 165H310M400 100H660M400 165H660"/></g>${svgText('Learner',180,72)}${svgText('- name: STRING',180,130)}${svgText('+ displayDetails()',180,200)}${svgText('Course',530,72)}${svgText('- title: STRING',530,130)}${svgText('+ enrol(learner)',530,200)}<path d="M310 140H400" stroke="#66758c" stroke-width="2"/><text x="326" y="125" fill="#52617b" font-size="12">enrols in</text>`,710,290,'Class diagram: Learner associated with Course');}
